object ReminderMessage {
    // New SimpleDateFormat instance per call, not a cached field -- SimpleDateFormat
    // isn't thread-safe and this is invoked from both DailyListViewModel's
    // viewModelScope coroutine and BootReminderReceiver's IO-dispatcher coroutine.
    fun build(context: Context, medicationName: String, dueAtEpochMillis: Long): Pair<String, String> {
        val time = SimpleDateFormat("h:mm a", Locale.getDefault()).format(Date(dueAtEpochMillis))
        val title = context.getString(R.string.reminder_title, medicationName)
        val text = context.getString(R.string.reminder_text, time)
        return title to text
    }
}
